import csv, sys

def read(path):
    with open(path, encoding="utf-8", newline="") as handle:
        return list(csv.reader(handle, strict=True))

def validate(original, candidate):
    if not original or not candidate:
        raise ValueError("empty table")
    if candidate[0] != original[0] + ["zh_CN"]:
        raise ValueError("unexpected header")
    if len(candidate) != len(original):
        raise ValueError("row count changed")
    for i, (old, new) in enumerate(zip(original[1:], candidate[1:]), start=2):
        if len(new) != len(candidate[0]):
            raise ValueError(f"row {i}: width")
        if new[:-1] != old:
            raise ValueError(f"row {i}: original cells changed")
        if not new[-1].strip():
            raise ValueError(f"row {i}: blank Chinese translation")
    return len(candidate)-1

if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.exit("usage: python validate_csv.py ORIGINAL CANDIDATE")
    try:
        count = validate(read(sys.argv[1]), read(sys.argv[2]))
    except (ValueError, OSError, csv.Error) as error:
        sys.exit(f"FAIL: {error}")
    print(f"PASS: {count} preserved rows; zh_CN added")
